 Map<String,Object> providerFacts(Path root)throws Exception {String script="import sqlite3,json,sys; c=sqlite3.connect('file:'+sys.argv[1]+'?mode=ro',uri=True); print(json.dumps({'documents':c.execute('SELECT COUNT(*) FROM document').fetchone()[0], 'publications':c.execute('SELECT COUNT(*) FROM publication_slot').fetchone()[0], 'grants':c.execute('SELECT actor,library,folder,can_read,can_publish,version FROM grant_record ORDER BY actor,library,folder').fetchall()}))";var process=new ProcessBuilder("/usr/bin/python3","-c",script,root.resolve("runtime/knowledge.sqlite").toString()).redirectErrorStream(true).start();assertTrue(process.waitFor(5,java.util.concurrent.TimeUnit.SECONDS));String output=new String(process.getInputStream().readNBytes(8192),java.nio.charset.StandardCharsets.UTF_8);assertEquals(0,process.exitValue(),output);return json.readValue(output,new com.fasterxml.jackson.core.type.TypeReference<Map<String,Object>>(){});}
